query:
-- 중복 이메일 점검
SELECT email, COUNT(*) as cnt FROM users WHERE email IS NOT NULL GROUP BY email HAVING COUNT(*) > 1;
-- 전체 이메일 현황
SELECT id, name, email, role, accountStatus, loginStatus FROM users ORDER BY email;

